async function resilientFetch(path,options={}){const method=(options.method||"GET").toUpperCase(),attempts=method==="GET"?3:1;let lastError;for(let attempt=0;attempt<attempts;attempt++){try{return await fetch(path,options)}catch(error){lastError=error;if(attempt+1<attempts)await wait(300*(attempt+1))}}throw new Error("Connexion locale momentanément interrompue")}
