  const roots=[];
  const categoryRank=new Map(knownCategories.map((category,index)=>[category,index]));
  const displayRank=category=>category==="__root__"?-1:(categoryRank.get(category)??Number.MAX_SAFE_INTEGER);
  for(const [category,items] of [...categories].sort((a,b)=>displayRank(a[0])-displayRank(b[0])||a[0].localeCompare(b[0],"fr"))){
    if(category==="__root__"){for(const item of items.filter(x=>!isBrowserEntry(x)).sort((a,b)=>b.seconds-a.seconds))roots.push(treeLeaf(item));const brave=items.filter(isBrowserEntry);if(brave.length)roots.push(browserNode(data,brave,0));continue}
    const children=[];for(const item of items.filter(x=>!isBrowserEntry(x)).sort((a,b)=>b.seconds-a.seconds))children.push(treeLeaf(item,1));const brave=items.filter(isBrowserEntry);if(brave.length)children.push(browserNode(data,brave,1));roots.push({id:`category:${category}`,kind:"category",label:category==="Applications non classées"?"Applications non classées":category,seconds:total(items),depth:0,payload:{category,target_keys:items.map(x=>x.key)},draggable:category!=="Applications non classées",children})
  }
  const categoryNodes=new Map(roots.filter(node=>node.kind==="category").map(node=>[node.payload.category,node]));
