function sessionTime(value){return new Date(value).toLocaleString("fr-FR",{dateStyle:"short",timeStyle:"medium"})}
function localDay(value){const date=new Date(value),year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,"0"),day=String(date.getDate()).padStart(2,"0");return `${year}-${month}-${day}`}
