function nextDay(day){const date=dayStart(day);date.setDate(date.getDate()+1);return localDay(date)}
function daysBetween(start,end){const days=[];for(let day=start;day<=end;day=nextDay(day))days.push(day);return days}
function sessionKind(item){return item.kind==="multimedia"?"Multimédia":item.kind==="web"?"PWA / site actif":"Programme"}
function timelineItem(item){if(item.kind==="multimedia"&&!String(item.key||"").startsWith("app:"))return {kind:"passive-item",label:item.label};return {kind:"target",target_key:item.key}}
function timelineItemData(item){return encodeURIComponent(JSON.stringify(timelineItem(item)))}
function sessionEntries(sessions,now){return sessions.map(item=>({item,opened:new Date(item.started_at),closed:item.ended_at?new Date(item.ended_at):now}))}
