function openNotification(ruleId="",requestedKind=""){const current=(state?.notification_rules||[]).find(item=>item.id===ruleId),kind=current?.kind||requestedKind;if(!["limited_app_start","limit_change","limit_warning","computer_block_warning","computer_block_change","pwa_login","usage_threshold","startup_reminder"].includes(kind))return;notificationDraft={id:current?.id||"",kind,label:current?.label||"",description:current?.description||"",target_key:current?.target_key||"",threshold_mode:current?.threshold_mode||"duration",threshold_percent:current?.threshold_percent||80,duration_seconds:current?.duration_seconds||3600,after_time:current?.after_time||"",valid_from:current?.valid_from||"",valid_from_time:current?.valid_from_time||"",valid_until:current?.valid_until||"",valid_until_time:current?.valid_until_time||"",warning_seconds:current?.warning_seconds||300,weekdays:[...(current?.weekdays||[])],enabled:current?.enabled!==false};closeChoiceMenus();if(kind==="limited_app_start"){notificationDraft.target_key="";saveNotificationDraft(true);return}if(kind==="limit_warning"&&!current){showNotificationWarningManager();return}if(["limit_warning","computer_block_warning"].includes(kind)){notificationDraft.target_key="";showNotificationWarning();return}if(kind==="usage_threshold"){showNotificationThresholdTypes();return}if(kind==="startup_reminder"){showNotificationWeekdays();return}saveNotificationDraft(true)}
