function showNotificationTargets(scope=""){let targets=[],back="types",title="Choisir une cible";if(notificationDraft?.kind==="usage_threshold"){const candidates=state?.merge_candidates||[];back="target-types";if(scope==="category"){title="Choisir une catégorie";targets=categoryTargets()}else if(scope==="site"){title="Choisir un site spécifique";targets=candidates.filter(item=>String(item.key).startsWith("site:"))}else{title="Choisir une application";targets=candidates.filter(item=>!String(item.key).startsWith("category:")&&!String(item.key).startsWith("site:"))}}else if(notificationDraft?.kind==="limited_app_start"){targets=(state?.merge_candidates||[]).filter(item=>!String(item.key).startsWith("category:"))}else if(notificationDraft?.kind==="limit_warning"){targets=[{target_key:"computer:all",label:"Tout l’ordinateur"},...categoryTargets(),...(state?.merge_candidates||[])]}else{targets=state?.limits||[]}const choices=targets.map(item=>{const key=item.target_key||item.key,label=key==="computer:all"||String(key).startsWith("category:")?item.label:targetPathLabel(item);return `<button data-notification-target="${encodeURIComponent(key)}"><strong>${esc(label)}</strong></button>`}).join("");$("#notification-target-menu").innerHTML=`<button class="choice-back" data-notification-back="${back}"><strong>← Retour</strong></button><p class="choice-heading">${title}</p>${choices||'<span class="empty">Aucune cible disponible.</span>'}`;showNotificationStep("#notification-target-menu",back)}
