async function saveNotificationDraft(enabled,{returnToWarningList=false}={}){if(!notificationDraft)return false;notificationDraft.enabled=notificationDraft.id?notificationDraft.enabled:enabled;$("#notification-workflow").hidden=true;const saved=await action({action:"set_notification_rule",rule:notificationDraft});if(saved&&returnToWarningList){notificationDraft=null;showNotificationWarningManager()}return saved}
