function categorySiblings(category){const parents=state?.category_parents||{},parent=parents[category]||"";return (state?.top_level_categories||state?.categories||[]).filter(name=>name!=="__root__"&&name!=="Applications non classées"&&(parents[name]||"")===parent)}
function reorderCategoryByOffset(category,offset){const siblings=categorySiblings(category),index=siblings.indexOf(category),destination=siblings[index+offset];if(destination)action({action:"reorder_category",category,destination,before:offset<0})}
function categoryPositionDialog(category){const siblings=categorySiblings(category).filter(name=>name!==category),positions=siblings.flatMap(destination=>[{destination,before:true,label:`Avant « ${destination} »`},{destination,before:false,label:`Après « ${destination} »`}]);if(!positions.length){toast("Aucune autre catégorie à ce niveau");return}const options=positions.map((position,index)=>`<option value="${index}">${esc(position.label)}</option>`).join("");openDialog(`Déplacer « ${category} »`,`<label>Nouvelle position<select name="position">${options}</select></label><small>Seule la disposition change. La hiérarchie et le contenu restent identiques.</small>`,form=>{const position=positions[Number(form.get("position"))];if(position)action({action:"reorder_category",category,destination:position.destination,before:position.before})})}
function siteCategoryPositionDialog(category){const siblings=(state?.site_categories||[]).filter(name=>name!==category),positions=siblings.flatMap(destination=>[{destination,before:true,label:`Avant « ${destination} »`},{destination,before:false,label:`Après « ${destination} »`}]);if(!positions.length){toast("Aucune autre sous-catégorie à ce niveau");return}const options=positions.map((position,index)=>`<option value="${index}">${esc(position.label)}</option>`).join("");openDialog(`Déplacer « ${category} »`,`<label>Nouvelle position<select name="position">${options}</select></label><small>Seule la disposition change. Les sites classés restent identiques.</small>`,form=>{const position=positions[Number(form.get("position"))];if(position)action({action:"reorder_site_category",category,destination:position.destination,before:position.before})})}
function contextActions(item){
  if(remoteMode&&!authState?.permissions?.manage_activity)return [];
  if(item.kind==="target"||item.kind==="other-sites")return [{label:"Sortir de non classé",run:()=>action({action:"make_root",target_key:item.target_key})},{separator:true},{label:"Renommer l’activité…",run:()=>openDialog("Renommer l’activité",'<label>Nouveau nom<input name="label" required></label>',f=>action({action:"rename_target",target_key:item.target_key,label:f.get("label")}))},{label:"Déplacer vers une catégorie…",run:()=>categoryDialog(item.target_key)},{label:"Retirer de la catégorie",run:()=>action({action:"set_category",target_key:item.target_key,category:""})},{label:"Fusionner dans une autre activité…",run:()=>mergeDialog(item.target_key)},{separator:true},{label:"Ne pas comptabiliser",run:()=>action({action:"exclude_target",target_key:item.target_key})},{label:"Supprimer définitivement…",danger:true,run:()=>{if(confirm("Supprimer définitivement tout l’historique de cette activité ?"))action({action:"delete_target",target_key:item.target_key})}}];
  if(item.kind==="other-site")return [{label:"Rendre spécifique",run:()=>action({action:"make_site_specific",browser:item.browser,host:item.host})},{label:"Déplacer dans une catégorie…",run:()=>siteCategoryDialog(item)},{label:"Ne pas comptabiliser",run:()=>action({action:"exclude_site",browser:item.browser,host:item.host})},{label:"Supprimer définitivement…",danger:true,run:()=>{if(confirm("Supprimer définitivement l’historique de ce site ?"))action({action:"delete_site",browser:item.browser,host:item.host})}}];
  if(item.kind==="category"){const siblings=categorySiblings(item.category),index=siblings.indexOf(item.category);return [{label:"Renommer la catégorie…",run:()=>openDialog("Renommer la catégorie",`<label>Nouveau nom<input name="label" value="${esc(item.category)}" required></label>`,f=>action({action:"rename_category",category:item.category,label:f.get("label")}))},{label:"Choisir la position…",run:()=>categoryPositionDialog(item.category)},{separator:true},...(index>0?[{label:"Monter dans l’affichage",run:()=>reorderCategoryByOffset(item.category,-1)}]:[]),...(index>=0&&index<siblings.length-1?[{label:"Descendre dans l’affichage",run:()=>reorderCategoryByOffset(item.category,1)}]:[]),{separator:true},{label:"Retirer la catégorie",run:()=>action({action:"clear_category",category:item.category})}]}
  if(item.kind==="site-category")return [{label:"Renommer la sous-catégorie…",run:()=>openDialog("Renommer la sous-catégorie",`<label>Nouveau nom<input name="label" value="${esc(item.category)}" required></label>`,f=>action({action:"rename_site_category",target_keys:item.target_keys,label:f.get("label")}))},{label:"Choisir la position…",run:()=>siteCategoryPositionDialog(item.category)},{label:"Retirer la sous-catégorie",run:()=>action({action:"clear_site_category",target_keys:item.target_keys,category:item.category})}];
  if(item.kind==="browser")return [{label:"Renommer le navigateur…",run:()=>openDialog("Renommer le navigateur",'<label>Nouveau nom<input name="label" required></label>',f=>action({action:"rename_browser",browser:item.browser,label:f.get("label")}))},{label:"Sortir de la catégorie",run:()=>action({action:"make_browser_root",browser:item.browser})},{label:"Retirer de la catégorie",run:()=>action({action:"clear_browser_category",browser:item.browser})}];
  if(item.kind==="passive-item")return [{label:"Ne pas comptabiliser dans l’usage passif",run:()=>action({action:"exclude_passive",label:item.label})}];
  if(item.kind==="excluded-target")return [{label:"Réactiver",run:()=>action({action:"unexclude_target",target_key:item.target_key})}];
  return []
}
function showContextMenu(event,item){const actions=contextActions(item);if(!actions.length)return;event.preventDefault();const menu=$("#context-menu");menu.innerHTML=actions.map((entry,index)=>entry.separator?"<hr>":`<button data-context-index="${index}" class="${entry.danger?"danger":""}">${esc(entry.label)}</button>`).join("");menu._actions=actions;menu.hidden=false;const width=240,height=Math.min(360,menu.scrollHeight);menu.style.left=`${Math.min(event.clientX,innerWidth-width-8)}px`;menu.style.top=`${Math.min(event.clientY,innerHeight-height-8)}px`}
function categoryDialog(key){openDialog("Classer l’activité",`<label>Catégorie<select name="category">${categoryOptions()}</select></label><label>Ou nouvelle catégorie<input name="new_category"></label>`,f=>action({action:"set_category",target_key:key,category:f.get("new_category")||f.get("category")}))}
function keysCategoryDialog(keys){openDialog("Déplacer la catégorie",`<label>Catégorie cible<select name="category">${categoryOptions()}</select></label><label>Ou nouvelle catégorie<input name="new_category"></label>`,f=>action({action:"set_category_for_keys",target_keys:keys,category:f.get("new_category")||f.get("category")}))}
function siteCategoryDialog(item){openDialog("Classer le site",`<label>Catégorie<select name="category">${categoryOptions()}</select></label><label>Ou nouvelle catégorie<input name="new_category"></label>`,f=>action({action:"categorize_site",browser:item.browser,host:item.host,category:f.get("new_category")||f.get("category")}))}
function mergeDialog(key){openDialog("Fusionner l’activité",`<label>Destination<select name="destination">${targetOptions()}</select></label>`,f=>{const destination=f.get("destination");if(destination!==key&&confirm("Toutes les durées seront déplacées vers l’activité choisie. Continuer ?"))action({action:"merge_target",target_key:key,destination_key:destination})})}

function dropTreeItem(source,destination){if(remoteMode&&!authState?.permissions?.manage_activity)return;if(!source||!destination)return;if(source.kind==="target"&&destination.kind==="target"&&source.target_key!==destination.target_key){if(confirm("Fusionner ces deux activités et déplacer tout l’historique ?"))action({action:"merge_target",target_key:source.target_key,destination_key:destination.target_key});return}if(destination.kind==="category"){if(source.kind==="other-site")action({action:"categorize_site",browser:source.browser,host:source.host,category:destination.category});else if(source.kind==="target")action({action:"set_category",target_key:source.target_key,category:destination.category});else if(source.kind==="category"&&source.category!==destination.category)action({action:"reorder_category",category:source.category,destination:destination.category,before:draggedCategoryBefore});else if(source.target_keys)action({action:"set_category_for_keys",target_keys:source.target_keys,category:destination.category});return}if(source.kind==="site-category"&&destination.kind==="site-category"&&source.category!==destination.category){action({action:"reorder_site_category",category:source.category,destination:destination.category,before:draggedCategoryBefore});return}if(destination.kind==="browser"&&source.kind==="target")action({action:"set_category",target_key:source.target_key,category:""});if(destination.kind==="site-category"&&source.kind==="target")action({action:"set_category",target_key:source.target_key,category:destination.category})}
function dragScrollStep(){dragScrollFrame=0;if(!draggedTreeItem||!dragScrollVelocity)return;const scroller=document.scrollingElement,before=scroller.scrollTop;scroller.scrollTop+=dragScrollVelocity;if(scroller.scrollTop===before){dragScrollVelocity=0;return}dragScrollFrame=requestAnimationFrame(dragScrollStep)}
function updateDragScroll(clientY){const edge=Math.min(150,innerHeight*.22),top=Math.max(0,edge-clientY),bottom=Math.max(0,clientY-(innerHeight-edge)),distance=Math.max(top,bottom);if(!distance){dragScrollVelocity=0;return}const intensity=Math.min(1,distance/edge),direction=bottom>top?1:-1;dragScrollVelocity=direction*(2+22*intensity*intensity);if(!dragScrollFrame)dragScrollFrame=requestAnimationFrame(dragScrollStep)}
function stopDragScroll(){dragScrollVelocity=0;if(dragScrollFrame)cancelAnimationFrame(dragScrollFrame);dragScrollFrame=0}

document.addEventListener("click",event=>{
  const tab=event.target.closest("[data-tab]");
  if(tab){
    closeChoiceMenus();
    $$('[data-tab]').forEach(item=>item.classList.toggle("active",item===tab));
    $$('.panel').forEach(panel=>panel.classList.toggle("active",panel.id===tab.dataset.tab));
    if(tab.dataset.tab==="analysis")loadAnalysis();
    else if(tab.dataset.tab==="notifications")loadNotifications();
    else if(tab.dataset.tab==="today"||tab.dataset.tab==="limits")load();
    else if(tab.dataset.tab==="settings"&&!remoteMode)loadRemoteUsers();
    return;
  }
  const button=event.target.closest("button");
  if(button?.dataset.workflowCancel){cancelWorkflow(button.dataset.workflowCancel);return}
  if(button?.dataset.manageUser){manageLocalUser(decodeURIComponent(button.dataset.manageUser));return}
  if(button?.dataset.deleteUser){const username=decodeURIComponent(button.dataset.deleteUser);if(confirm(`Supprimer l’utilisateur ${username} ?`)){api(`/api/v1/backend/users/${encodeURIComponent(username)}`,{method:"DELETE"}).then(()=>{toast("Utilisateur supprimé");loadRemoteUsers()}).catch(error=>toast(error.message))}return}
  if(button?.dataset.analysisType){showAnalysisPanel(button.dataset.analysisType);return}
  if(button?.dataset.statsKind){showStatsTargets(button.dataset.statsKind);return}
  if(button?.dataset.statsChoice!==undefined){selectedStatsChoiceIndex=Number(button.dataset.statsChoice);$("#analysis-stats-target-menu").hidden=true;$("#analysis-stats-period-menu").hidden=false;return}
  if(button?.dataset.statsPeriod){const days=analysisHistory?.daily_stats||[];if(!days.length)return;const last=days[days.length-1].date;if(button.dataset.statsPeriod==="custom"){$("#analysis-stats-period-menu").hidden=true;$("#analysis-stats-custom-period").hidden=false;return}const count=Number(button.dataset.statsPeriod),start=button.dataset.statsPeriod==="today"?last:button.dataset.statsPeriod==="all"?days[0].date:days[Math.max(0,days.length-count)].date;renderAnalysisStats(selectedStatsChoiceIndex,start,last);return}
  if(button?.dataset.analysisSessionIndex!==undefined){showAnalysisClassifications(button.dataset.analysisSessionIndex);return}
  if(button?.dataset.analysisChoiceIndex!==undefined){selectedAnalysisChoiceIndex=Number(button.dataset.analysisChoiceIndex);renderSelectedAnalysis();return}
  if(button?.dataset.analysisBack){const step=button.dataset.analysisBack;if(step==="types"){$("#analysis-stats-panel").hidden=true;$("#analysis-timeline-panel").hidden=true;$("#analysis-type-menu").hidden=false;$("#new-analysis").setAttribute("aria-expanded","true")}else if(step==="stats-kind"){$("#analysis-stats-kind-menu").hidden=false;$("#analysis-stats-target-menu").hidden=true}else if(step==="stats-target"){showStatsTargets(analysisStatsChoices[selectedStatsChoiceIndex]?.kind||"category")}else if(step==="stats-period"){$("#analysis-stats-custom-period").hidden=true;$("#analysis-stats-results").hidden=true;$("#analysis-stats-period-menu").hidden=false}else if(step==="sessions"){$("#analysis-session-menu").hidden=false;$("#analysis-classification-menu").hidden=true;$("#analysis-sessions").hidden=true}else if(step==="classification")showAnalysisClassifications(selectedAnalysisSessionIndex);return}
  if(!button||!state)return;
  if(button.dataset.categoryPosition){categoryPositionDialog(decodeURIComponent(button.dataset.categoryPosition));return}
  if(button.dataset.siteCategoryPosition){siteCategoryPositionDialog(decodeURIComponent(button.dataset.siteCategoryPosition));return}
  if(button.dataset.limitTargetType){const type=button.dataset.limitTargetType;if(type==="computer")openComputerBlock();else openLimit("",type);return}
  if(button.dataset.notificationType){closeChoiceMenus();openNotification("",button.dataset.notificationType);return}
  if(button.dataset.targetOpen){const node=targetSelectorNodes.get(decodeURIComponent(button.dataset.targetOpen));if(node){if(targetSelectorNode)targetSelectorParents.push(targetSelectorNode);targetSelectorNode=node;renderTargetSelector()}return}
  if(button.dataset.targetSelect){const targetKey=decodeURIComponent(button.dataset.targetSelect);if(targetSelectorOwner==="limit"){if(targetKey==="computer:all")openComputerBlock();else beginLimitForTarget(targetKey)}else{notificationDraft.target_key=targetKey;notificationDraft.threshold_mode==="time"?showNotificationHour():showNotificationDuration()}return}
  if(button.hasAttribute("data-target-tree-back")){if(targetSelectorNode){targetSelectorNode=targetSelectorParents.pop()||null;renderTargetSelector()}else if(targetSelectorOwner==="notification")showNotificationThresholdTypes();else cancelWorkflow("limit");return}
  if(button.dataset.notificationThresholdMode){notificationDraft.threshold_mode=button.dataset.notificationThresholdMode;showNotificationThresholdTargetTypes();return}
  if(button.dataset.notificationTargetType){const type=button.dataset.notificationTargetType;if(type==="computer"){notificationDraft.target_key="computer:all";showNotificationDuration()}else showNotificationTargets(type);return}
  if(button.dataset.limitTarget){limitDraft.target_key=decodeURIComponent(button.dataset.limitTarget);showLimitValidityStep();return}
  if(button.dataset.limitValidity){if(button.dataset.limitValidity==="permanent"){limitDraft.block_during_validity=false;limitDraft.valid_from="";limitDraft.valid_from_time="";limitDraft.valid_until="";limitDraft.valid_until_time="";continueAfterValidity()}else{limitDraft.block_during_validity=true;showLimitValidityForm()}return}
  if(button.dataset.limitBack){const step=button.dataset.limitBack;if(step==="types"){if(limitDraft?.editing)cancelWorkflow("limit");else renderTargetSelector()}else if(step==="targets")renderTargetSelector();else if(step==="validity")showLimitValidityStep();else if(step==="duration")showLimitDurationStep();else if(step==="extension")showLimitExtensionStep();else if(step==="warning")showLimitWarningStep();return}
  if(button.dataset.notificationTarget){notificationDraft.target_key=decodeURIComponent(button.dataset.notificationTarget);if(notificationDraft.kind==="usage_threshold")showNotificationDuration();else showNotificationWarning();return}
  if(button.dataset.notificationThreshold){notificationDraft.threshold_percent=Number(button.dataset.notificationThreshold);saveNotificationDraft(true);return}
  if(button.dataset.notificationValidity){if(button.dataset.notificationValidity==="permanent"){notificationDraft.valid_from="";notificationDraft.valid_from_time="";notificationDraft.valid_until="";notificationDraft.valid_until_time="";saveNotificationDraft(true)}else showNotificationValidityForm();return}
  if(button.hasAttribute("data-notification-warning-add")){startNotificationWarning();return}
  if(button.hasAttribute("data-notification-warning-manage")){closeChoiceMenus();showNotificationWarningManager();return}
  if(button.dataset.notificationWarningGroupToggle){const rules=(state.notification_rules||[]).filter(rule=>rule.kind==="limit_warning"),enabled=!rules.every(rule=>rule.enabled);updateNotificationWarningGroup(enabled);return}
  if(button.hasAttribute("data-notification-warning-group-remove")&&confirm("Supprimer toutes les durées de préavis ?")){removeNotificationWarningGroup();return}
  if(button.dataset.notificationWeekday!==undefined){const day=Number(button.dataset.notificationWeekday),days=new Set(notificationDraft.weekdays);days.has(day)?days.delete(day):days.add(day);notificationDraft.weekdays=[...days].sort();showNotificationWeekdays();return}
  if(button.hasAttribute("data-notification-weekdays-done")){saveNotificationDraft(true);return}
  if(button.dataset.notificationBack){const step=button.dataset.notificationBack;if(step==="types"||step==="previous"&&notificationPreviousStep==="types"){$("#notification-workflow").hidden=true;$("#notification-type-menu").hidden=false;$("#new-notification").setAttribute("aria-expanded","true")}else if(step==="threshold-type")showNotificationThresholdTypes();else if(step==="target-types")showNotificationThresholdTargetTypes();else if(step==="threshold-value"){notificationDraft.threshold_mode==="time"?showNotificationHour():showNotificationDuration()}else if(step==="validity")showNotificationValidity();else if(step==="warning-list")showNotificationWarningManager();else if(step==="target"||notificationPreviousStep==="target")renderTargetSelector();else if(notificationPreviousStep==="warning")showNotificationWarning();else if(notificationPreviousStep==="weekdays")showNotificationWeekdays();return}
  if(button.dataset.limitToggle){const item=state.limits.find(entry=>entry.target_key===decodeURIComponent(button.dataset.limitToggle));if(!item){toast("Limite introuvable");return}const command=limitCommand(item,!item.enabled);item.enabled=!item.enabled;renderLimits(state);action(command);return}
  if(button.dataset.limitEdit)openLimit(decodeURIComponent(button.dataset.limitEdit));
  if(button.dataset.limitReset)action({action:"reset_limit",target_key:decodeURIComponent(button.dataset.limitReset)});
  if(button.dataset.limitRemove&&confirm("Retirer cette limite ?"))action({action:"remove_limit",target_key:decodeURIComponent(button.dataset.limitRemove)});
  if(button.dataset.computerBlockToggle){const block=state.computer_block;if(!block?.mode){toast("Limitation de l’ordinateur introuvable");return}block.enabled=block.enabled===false;renderLimits(state);action({action:"set_computer_block_enabled",enabled:block.enabled});return}
  if(button.dataset.notificationToggle){const rule=(state.notification_rules||[]).find(entry=>entry.id===decodeURIComponent(button.dataset.notificationToggle));if(!rule){toast("Notification introuvable");return}rule.enabled=!rule.enabled;renderNotifications(state);action({action:"set_notification_rule",rule});return}
  if(button.dataset.notificationEdit)openNotification(decodeURIComponent(button.dataset.notificationEdit));
  if(button.dataset.notificationWarning)openNotificationWarning(decodeURIComponent(button.dataset.notificationWarning));
  if(button.dataset.notificationRemove&&confirm("Supprimer cette règle de notification ?"))action({action:"remove_notification_rule",rule_id:decodeURIComponent(button.dataset.notificationRemove)});
  if(button.hasAttribute("data-computer-block-clear")&&confirm("Lever l’interdiction d’utiliser l’ordinateur ?"))action({action:"clear_computer_block"});
});
document.addEventListener("click",event=>{const toggle=event.target.closest("[data-tree-toggle]");if(toggle){toggleTreeNode(toggle.dataset.treeToggle);renderTree(state,$("#analysis").classList.contains("active")?"#analysis-usage":"#today-usage");return}const contextButton=event.target.closest("[data-context-index]");if(contextButton){const entry=$("#context-menu")._actions[Number(contextButton.dataset.contextIndex)];hideContextMenu();entry?.run();return}if(!event.target.closest("#context-menu"))hideContextMenu()});
