document.addEventListener("dragover",event=>{if(draggedTreeItem)updateDragScroll(event.clientY);const row=event.target.closest("[data-tree-item]");if(!row)return;const destination=decodeTreeItem(row);if(["category","site-category"].includes(draggedTreeItem?.kind)){const parents=state?.category_parents||{},siblings=draggedTreeItem.kind==="category"?destination?.kind==="category"&&(parents[draggedTreeItem.category]||"")===(parents[destination.category]||""):destination?.kind==="site-category";if(!siblings||draggedTreeItem.category===destination.category)return;event.preventDefault();event.dataTransfer.dropEffect="move";clearDropTargets();draggedCategoryBefore=event.clientY<row.getBoundingClientRect().top+row.getBoundingClientRect().height/2;row.classList.add(draggedCategoryBefore?"drop-before":"drop-after");return}if(["target","category","browser","site-category"].includes(destination.kind)){event.preventDefault();event.dataTransfer.dropEffect="move";clearDropTargets();row.classList.add("drop-target")}});
